public class PointTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Point p = new Point(3, 7);
        check("x() accessor", 3, p.x());
        check("y() accessor", 7, p.y());
        check("value equality", new Point(2, 5), new Point(2, 5));
        check("distance 3-4-5 triangle", 5.0, new Point(0, 0).distanceTo(new Point(3, 4)));
        check("distance shifted 3-4-5", 5.0, new Point(1, 1).distanceTo(new Point(4, 5)));
        check("vertical distance", 7.0, new Point(0, 0).distanceTo(new Point(0, 7)));
        check("distance to self", 0.0, new Point(2, -1).distanceTo(new Point(2, -1)));
        check("origin()", new Point(0, 0), Point.origin());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

