public record Point(int x, int y) {

    public double distanceTo(Point other) {
        double dx = other.x - x;
        double dy = other.y - y;
        return Math.sqrt(dx * dx + dy * dy);
    }

    public static Point origin() {
        return new Point(0, 0);
    }
}
